package com.edgecloud.device.service;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.edgecloud.device.entity.*;import com.edgecloud.device.exception.*;import com.edgecloud.device.repository.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.data.domain.*;import org.springframework.test.util.ReflectionTestUtils;
@ExtendWith(MockitoExtension.class) class DeviceHeartbeatServiceImplTest {@Mock EdgeDeviceRepository devices;@Mock DeviceConfigurationRepository configs;@Mock DeviceHeartbeatHistoryRepository history;DeviceHeartbeatServiceImpl service;UUID id=UUID.randomUUID();EdgeDevice device;
 @BeforeEach void setup(){service=new DeviceHeartbeatServiceImpl(devices,configs,history,new HeartbeatPolicyServiceImpl());device=new EdgeDevice();ReflectionTestUtils.setField(device,"id",id);device.setDeviceName("node");device.setDeviceType("EDGE");device.setIpAddress("10.0.0.1");device.prePersist();lenient().when(devices.findById(id)).thenReturn(Optional.of(device));lenient().when(devices.findByIdForUpdate(id)).thenReturn(Optional.of(device));lenient().when(configs.findById(id)).thenReturn(Optional.empty());lenient().when(devices.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void recordsFirstHeartbeatAndPersistsHistory(){LocalDateTime at=LocalDateTime.now().minusSeconds(1);var r=service.record(id,at);assertThat(r.status()).isEqualTo(HeartbeatStatus.ONLINE);assertThat(device.getLastHeartbeat()).isEqualTo(at);assertThat(device.getOnlineSince()).isEqualTo(at);verify(history).save(argThat(e->e.getEventType()==HeartbeatEventType.RECEIVED));}
 @Test void rejectsUnknownInactiveAndFuture(){when(devices.findByIdForUpdate(id)).thenReturn(Optional.empty());assertThatThrownBy(()->service.record(id,null)).isInstanceOf(DeviceNotFoundException.class);when(devices.findByIdForUpdate(id)).thenReturn(Optional.of(device));device.setActive(false);assertThatThrownBy(()->service.record(id,null)).isInstanceOf(InvalidDeviceLifecycleException.class);device.setActive(true);assertThatThrownBy(()->service.record(id,LocalDateTime.now().plusHours(1))).isInstanceOf(IllegalArgumentException.class);}
 @Test void evaluatesDelayedOfflineAndRecoveryWithoutDuplicateTransition(){LocalDateTime now=LocalDateTime.now();device.setLastHeartbeat(now.minusSeconds(70));device.setOnlineSince(now.minusMinutes(5));device.setStatus(DeviceStatus.ONLINE);device.setHeartbeatState(HeartbeatStatus.HEALTHY);when(devices.findByActiveTrue()).thenReturn(List.of(device));service.evaluateAll(now);assertThat(device.getHeartbeatState()).isEqualTo(HeartbeatStatus.DELAYED);assertThat(device.getConsecutiveMissedHeartbeats()).isEqualTo(2);service.evaluateAll(now.plusSeconds(30));assertThat(device.getStatus()).isEqualTo(DeviceStatus.OFFLINE);service.record(id,now.plusSeconds(31));assertThat(device.getLastRecoveryAt()).isEqualTo(now.plusSeconds(31));assertThat(device.getStatus()).isEqualTo(DeviceStatus.ONLINE);verify(history).save(argThat(e->e.getEventType()==HeartbeatEventType.RECOVERED));}
 @Test void returnsOrderedPaginatedHistoryAndStatistics(){DeviceHeartbeatHistory event=new DeviceHeartbeatHistory(id,HeartbeatEventType.RECEIVED,LocalDateTime.now(),HeartbeatStatus.UNKNOWN,HeartbeatStatus.ONLINE,0);ReflectionTestUtils.setField(event,"id",1L);when(history.findByDeviceIdOrderByHeartbeatAtDescIdDesc(eq(id),any())).thenReturn(new PageImpl<>(List.of(event),PageRequest.of(0,10),1));when(history.countByDeviceId(id)).thenReturn(5L);when(history.countByDeviceIdAndEventTypeInAndHeartbeatAtBetween(eq(id),anyList(),any(),any())).thenReturn(2L);when(history.countByDeviceIdAndEventType(id,HeartbeatEventType.RECOVERED)).thenReturn(1L);when(history.countByDeviceIdAndEventType(id,HeartbeatEventType.OFFLINE)).thenReturn(2L);assertThat(service.history(id,0,10).events()).hasSize(1);var statistics=service.statistics(id);assertThat(statistics.totalRecorded()).isEqualTo(5);assertThat(statistics.receivedLast24Hours()).isEqualTo(2);assertThat(statistics.recoveryCount()).isEqualTo(1);assertThatThrownBy(()->service.history(id,-1,10)).isInstanceOf(IllegalArgumentException.class);}
}
